from pathlib import Path
import json,subprocess
R=Path(__file__).resolve().parents[1];D=R/'marketing/assets/hyundai-merge-20261012';release=json.loads((D/'release.json').read_text());before=json.loads((D/'cms-before.json').read_text())
js='const release='+json.dumps(release,ensure_ascii=False)+';const before='+json.dumps(before,ensure_ascii=False)+';'+r'''
const{Pool}=require('pg');(async()=>{let p=new Pool({connectionString:process.env.DB_VIBERS_MAIN_URL,max:1}),d=await p.connect();try{await d.query('BEGIN');for(const[id,patch]of Object.entries(release.patches)){let b=await d.query("SELECT payload,status FROM semologo.logo_posts WHERE id=$1 FOR UPDATE",[id]);if(b.rowCount!==1||b.rows[0].status!=='published')throw Error('Identity '+id);const old=before.find(x=>x.id===id).payload;if(b.rows[0].payload.presentation&&JSON.stringify(b.rows[0].payload.presentation)!==JSON.stringify(old.presentation))throw Error('Representative changed '+id);if(b.rows[0].payload.merged_into&&b.rows[0].payload.merged_into!=='hyundai')throw Error('Different merge '+id);await d.query('UPDATE semologo.logo_posts SET payload=payload||$2::jsonb,updated_at=now() WHERE id=$1',[id,JSON.stringify(patch)]);if(id!=='hyundai'){let links=await d.query('SELECT target_brand_id FROM semologo.logo_content_merges WHERE source_brand_id=$1',[id]);if(links.rows.some(x=>x.target_brand_id!=='hyundai'))throw Error('Merge link conflict');await d.query("INSERT INTO semologo.logo_content_merges(source_brand_id,target_brand_id,reason,evidence) VALUES($1,'hyundai','현대자동차 동일 브랜드 시각 검수 · 가로/세로/심볼 통합',$2::jsonb) ON CONFLICT(source_brand_id) DO NOTHING",[id,JSON.stringify({source:id,target:'hyundai',checked_at:'2026-10-12',original_preserved:true})]);}}await d.query('COMMIT');console.log('PASS Hyundai representative preserved; 3 duplicate records linked, originals retained')}catch(e){await d.query('ROLLBACK');throw e}finally{d.release();await p.end()}})().catch(e=>{console.error(e.message);process.exitCode=1});'''
subprocess.run(['ssh','vibers','docker exec -i semologo node -'],input=js,text=True,check=True)
